<?php
require __DIR__.'/api/auth.php';
$pdo=db();$pdo->exec("CREATE TABLE IF NOT EXISTS password_reset_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,code_hash VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,used_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_reset_user_created(user_id,created_at),CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$sent=false;$done=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=(string)($_POST['action']??'request');if($action==='request'){$email=strtolower(trim((string)($_POST['email']??'')));$s=$pdo->prepare('SELECT id,email FROM users WHERE email=? AND active=1');$s->execute([$email]);$user=$s->fetch();if($user){$s=$pdo->prepare('SELECT COUNT(*) FROM password_reset_codes WHERE user_id=? AND created_at>DATE_SUB(NOW(),INTERVAL 1 HOUR)');$s->execute([$user['id']]);if((int)$s->fetchColumn()<3){$code=(string)random_int(100000,999999);$pdo->prepare('INSERT INTO password_reset_codes(user_id,code_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 15 MINUTE))')->execute([$user['id'],password_hash($code,PASSWORD_DEFAULT)]);$_SESSION['reset_id']=(int)$pdo->lastInsertId();$_SESSION['reset_email']=$email;$body="Your SPECTECHNOLOGY password reset code is: {$code}\n\nThe code is valid for 15 minutes. If you did not request it, ignore this message.";@mail($email,'SPECTECHNOLOGY — password reset code',$body,"From: office@spectechnology.pl\r\nReply-To: office@spectechnology.pl\r\nContent-Type: text/plain; charset=UTF-8",'-f office@spectechnology.pl');}}$sent=true;}elseif($action==='reset'){$id=(int)($_SESSION['reset_id']??0);$code=trim((string)($_POST['code']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm']??'');$s=$pdo->prepare('SELECT p.*,u.email FROM password_reset_codes p JOIN users u ON u.id=p.user_id WHERE p.id=? AND p.used_at IS NULL AND p.expires_at>NOW()');$s->execute([$id]);$reset=$s->fetch();if(!$reset||$reset['attempts']>=5){$error='Code expired or too many attempts.';}elseif(!password_verify($code,$reset['code_hash'])){$pdo->prepare('UPDATE password_reset_codes SET attempts=attempts+1 WHERE id=?')->execute([$id]);$error='Incorrect code.';}elseif(strlen($password)<8){$error='Password must contain at least 8 characters.';}elseif($password!==$confirm){$error='Passwords do not match.';}else{$pdo->beginTransaction();$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$reset['user_id']]);$pdo->prepare('UPDATE password_reset_codes SET used_at=NOW() WHERE id=?')->execute([$id]);$pdo->commit();unset($_SESSION['reset_id'],$_SESSION['reset_email']);$done=true;}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forgot password — SPECTECHNOLOGY</title><link rel="stylesheet" href="/assets/site-v13.css"><link rel="stylesheet" href="/assets/portal.css"></head><body class="portal"><main class="auth-card"><a href="/" class="portal-logo"><img src="/noBgColor-dark.png" alt="SPECTECHNOLOGY"></a><p class="eyebrow">ACCOUNT RECOVERY</p><h1>Forgot password / Nie pamiętam hasła</h1><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif?><?php if($done):?><p class="notice">Password changed successfully.</p><a class="primary" href="/login.php">Sign in / Zaloguj się</a><?php elseif($sent||!empty($_SESSION['reset_id'])):?><p>Enter the six-digit code sent to your email and choose a new password. The code is valid for 15 minutes.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="reset"><label>Verification code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code"></label><label>New password<input type="password" name="password" minlength="8" required autocomplete="new-password"></label><label>Repeat password<input type="password" name="confirm" minlength="8" required autocomplete="new-password"></label><button class="primary">Change password</button></form><?php else:?><p>Enter the email address assigned to your account.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="request"><label>Email<input type="email" name="email" required autocomplete="email"></label><button class="primary">Send verification code</button></form><?php endif?><a href="/login.php">← Sign in / Zaloguj się</a></main></body></html>